edits.before:
if (c === 0) {
    html += '<button class="pika-prev" type="button" data-pika-year="' + year + '" data-pika-month="' + (month === 0 ? 11 : month - 1) + '">' + opts.i18n.previousMonth + '</button>';
}

edits.after:
if (c === 0) {
    html += '<button class="pika-prev" type="button" tabindex="-1" data-pika-year="' + year + '" data-pika-month="' + (month === 0 ? 11 : month - 1) + '">' + opts.i18n.previousMonth + '</button>';
}

edits.before:
if (c === numberOfMonths - 1) {
    html += '<button class="pika-next" type="button" data-pika-year="' + (month === 11 ? year + 1 : year) + '" data-pika-month="' + (month === 11 ? 0 : month + 1) + '">' + opts.i18n.nextMonth + '</button>';
}

edits.after:
if (c === numberOfMonths - 1) {
    html += '<button class="pika-next" type="button" tabindex="-1" data-pika-year="' + (month === 11 ? year + 1 : year) + '" data-pika-month="' + (month === 11 ? 0 : month + 1) + '">' + opts.i18n.nextMonth + '</button>';
}
